def build(world):
    def walk_near(tx, ty, distance, avoid):
        moves = [("N", 0, -1), ("E", 1, 0), ("S", 0, 1), ("W", -1, 0)]
        for _ in range(80):
            sx, sy = world.tile()
            if abs(sx - tx) <= distance and abs(sy - ty) <= distance and (sx, sy) not in avoid:
                return True

            blocked = set(world.blocked_tiles())
            for e in world.entities():
                if e.kind == "wall":
                    blocked.add((int(math.floor(e.x)), int(math.floor(e.y))))

            queue = [(sx, sy)]
            parent = {(sx, sy): None}
            first = {(sx, sy): None}
            found = None
            i = 0
            lo_x = min(sx, tx) - 20
            hi_x = max(sx, tx) + 20
            lo_y = min(sy, ty) - 20
            hi_y = max(sy, ty) + 20

            while i < len(queue):
                p = queue[i]
                i += 1
                if abs(p[0] - tx) <= distance and abs(p[1] - ty) <= distance and p not in avoid:
                    found = p
                    break
                for direction, dx, dy in moves:
                    q = (p[0] + dx, p[1] + dy)
                    if q in parent or q in blocked:
                        continue
                    if q[0] < lo_x or q[0] > hi_x or q[1] < lo_y or q[1] > hi_y:
                        continue
                    parent[q] = p
                    if p == (sx, sy):
                        first[q] = direction
                    else:
                        first[q] = first[p]
                    queue.append(q)

            if found is None:
                return False
            direction = first[found]
            if direction is None:
                return True
            before = world.tile()
            if not world.move(direction, "step") or world.tile() == before:
                return False
        return False

    def fuel_machine(kind, x, y):
        target = None
        best = 1000000.0
        for e in world.entities():
            if e.kind == kind:
                d = abs(e.x - (x + 1)) + abs(e.y - (y + 1))
                if d < best:
                    target = e
                    best = d
        if target is not None:
            world.give(target, "coal", 20)

    ores = world.ore_tiles("iron-ore")
    if not ores:
        p = world.patch()
        if p is not None:
            walk_near(int(math.floor(p[0])), int(math.floor(p[1])), 4, set())
            ores = world.ore_tiles("iron-ore")
    if not ores:
        return

    candidates = set()
    for ox, oy in ores:
        candidates.add((ox, oy))
        candidates.add((ox - 1, oy))
        candidates.add((ox, oy - 1))
        candidates.add((ox - 1, oy - 1))

    hard = set(world.blocked_tiles())
    for e in world.entities():
        if e.kind == "wall":
            hard.add((int(math.floor(e.x)), int(math.floor(e.y))))

    attempts = 0
    for x, y in sorted(candidates):
        if attempts >= 80:
            break
        attempts += 1

        clear = True
        for px in range(x, x + 2):
            for py in range(y, y + 2):
                if (px, py) in hard:
                    clear = False
        for px in range(x, x + 2):
            for py in range(y + 2, y + 4):
                if (px, py) in hard:
                    clear = False
        if not clear:
            continue

        avoid = set()
        for px in range(x, x + 2):
            for py in range(y, y + 4):
                avoid.add((px, py))
        if not walk_near(x, y, 3, avoid):
            continue

        if not world.place("burner-mining-drill", x, y, "S"):
            continue
        if not world.place("stone-furnace", x, y + 2, "N"):
            for e in world.entities():
                if e.kind == "mining-drill":
                    world.mine(e)
                    break
            continue

        fuel_machine("mining-drill", x, y)
        fuel_machine("furnace", x, y + 2)
        return

