def build(world):
    ore = world.ore_tiles("iron-ore")
    if not ore:
        return

    blocked = set(world.blocked_tiles())
    entities = world.entities()
    candidates = set()

    for ox, oy in ore:
        for x in (ox - 1, ox):
            for y in (oy - 1, oy):
                drill_cells = [(x, y), (x + 1, y), (x, y + 1), (x + 1, y + 1)]
                furnace_cells = [
                    (x + 1, y + 2), (x + 2, y + 2),
                    (x + 1, y + 3), (x + 2, y + 3)
                ]
                cells = drill_cells + furnace_cells
                if any(cell in blocked for cell in cells):
                    continue

                occupied = False
                for e in entities:
                    if e.kind == "item-entity":
                        continue
                    if e.kind == "wall":
                        ex = math.floor(e.x)
                        ey = math.floor(e.y)
                        if (ex, ey) in cells:
                            occupied = True
                            break
                    elif e.kind == "furnace" or e.kind == "mining-drill":
                        if (abs(e.x - (x + 1)) <= 1 and abs(e.y - (y + 1)) <= 1) or (
                            abs(e.x - (x + 2)) <= 1 and abs(e.y - (y + 3)) <= 1
                        ):
                            occupied = True
                            break
                if not occupied:
                    candidates.add((x, y))

    px, py = world.me()
    ranked = []
    for x, y in candidates:
        ranked.append((abs(px - (x + 3)) + abs(py - (y + 1)), x, y))
    ranked.sort()

    for score, x, y in ranked:
        inv = world.inventory()
        if inv.get("burner-mining-drill", 0) <= 0:
            return
        if inv.get("stone-furnace", 0) <= 0 or inv.get("coal", 0) < 40:
            return

        target_x = x + 3
        target_y = y + 1
        stuck = 0

        while world.decisions_left() > 0:
            tx, ty = world.tile()
            in_range = (
                max(abs(tx - x), abs(ty - y)) <= 5
                and max(abs(tx - (x + 1)), abs(ty - (y + 2))) <= 5
            )
            on_machine = (
                x <= tx <= x + 1 and y <= ty <= y + 1
            ) or (
                x + 1 <= tx <= x + 2 and y + 2 <= ty <= y + 3
            )
            if in_range and not on_machine:
                break

            mx, my = world.me()
            dx = target_x - mx
            dy = target_y - my
            dirs = []
            if abs(dx) >= abs(dy):
                if dx > 0:
                    dirs.append("E")
                elif dx < 0:
                    dirs.append("W")
                if dy > 0:
                    dirs.append("S")
                elif dy < 0:
                    dirs.append("N")
            else:
                if dy > 0:
                    dirs.append("S")
                elif dy < 0:
                    dirs.append("N")
                if dx > 0:
                    dirs.append("E")
                elif dx < 0:
                    dirs.append("W")
            for d in ("N", "E", "S", "W"):
                if d not in dirs:
                    dirs.append(d)

            moved = False
            for d in dirs:
                before = world.me()
                world.move(d, "step")
                after = world.me()
                if abs(after[0] - before[0]) + abs(after[1] - before[1]) > 0.05:
                    moved = True
                    break

            if moved:
                stuck = 0
            else:
                stuck += 1
                if stuck >= 6:
                    break

        if world.decisions_left() <= 0:
            return

        tx, ty = world.tile()
        in_range = (
            max(abs(tx - x), abs(ty - y)) <= 5
            and max(abs(tx - (x + 1)), abs(ty - (y + 2))) <= 5
        )
        on_machine = (
            x <= tx <= x + 1 and y <= ty <= y + 1
        ) or (
            x + 1 <= tx <= x + 2 and y + 2 <= ty <= y + 3
        )
        if not in_range or on_machine:
            continue

        if not world.place("burner-mining-drill", x, y, "S"):
            continue
        if not world.place("stone-furnace", x + 1, y + 2, "N"):
            return

        drill_row = None
        furnace_row = None
        for e in world.entities():
            if e.kind == "mining-drill" and abs(e.x - (x + 1)) < 0.1 and abs(e.y - (y + 1)) < 0.1:
                drill_row = e.row
            if e.kind == "furnace" and abs(e.x - (x + 2)) < 0.1 and abs(e.y - (y + 3)) < 0.1:
                furnace_row = e.row

        if drill_row is not None:
            world.give(drill_row, "coal", 20)
        if furnace_row is not None:
            world.give(furnace_row, "coal", 20)
        return

