def build(world):
    def occupied_tiles():
        occupied = set(world.blocked_tiles())
        for e in world.entities():
            if e.kind == "wall":
                occupied.add((int(e.x), int(e.y)))
            elif e.kind in ("furnace", "mining-drill", "container", "other"):
                left = int(e.x) - 1
                top = int(e.y) - 1
                for dx in range(2):
                    for dy in range(2):
                        occupied.add((left + dx, top + dy))
        return occupied

    def clear_square(x, y, occupied):
        for dx in range(2):
            for dy in range(2):
                if (x + dx, y + dy) in occupied:
                    return False
        return True

    def walk_to(tx, ty):
        while True:
            sx, sy = world.tile()
            if abs(sx - tx) + abs(sy - ty) <= 3:
                return True
            if world.decisions_left() <= 4:
                return False

            forbidden = occupied_tiles()
            low_x = min(sx, tx) - 12
            high_x = max(sx, tx) + 12
            low_y = min(sy, ty) - 12
            high_y = max(sy, ty) + 12

            queue = [(sx, sy)]
            parent = {(sx, sy): None}
            directions = [
                (0, -1, "N"),
                (1, 0, "E"),
                (0, 1, "S"),
                (-1, 0, "W")
            ]
            goal = None
            index = 0

            while index < len(queue):
                current = queue[index]
                index += 1
                x, y = current
                if abs(x - tx) + abs(y - ty) <= 3:
                    goal = current
                    break

                for dx, dy, direction in directions:
                    nx = x + dx
                    ny = y + dy
                    next_tile = (nx, ny)
                    if nx < low_x or nx > high_x or ny < low_y or ny > high_y:
                        continue
                    if next_tile in parent or next_tile in forbidden:
                        continue
                    parent[next_tile] = (current, direction)
                    queue.append(next_tile)

            if goal is None:
                return False

            path = []
            current = goal
            while parent[current] is not None:
                previous, direction = parent[current]
                path.append(direction)
                current = previous
            path.reverse()

            for direction in path:
                if world.decisions_left() <= 4:
                    return False
                if not world.move(direction, "step"):
                    return False

    def find_machine(kind, x, y):
        best = None
        best_distance = 1000000
        for e in world.entities():
            if e.kind == kind:
                distance = abs(e.x - (x + 1)) + abs(e.y - (y + 1))
                if distance < best_distance:
                    best = e
                    best_distance = distance
        if best_distance <= 1:
            return best
        return None

    ore = world.ore_tiles("iron-ore")
    if not ore:
        marker = world.patch()
        if marker is not None:
            walk_to(int(marker[0]), int(marker[1]))
            ore = world.ore_tiles("iron-ore")

    occupied = occupied_tiles()
    candidates = []
    seen = set()
    px, py = world.tile()

    for ox, oy in ore:
        for x in (ox - 1, ox):
            for y in (oy - 1, oy):
                if (x, y) in seen:
                    continue
                seen.add((x, y))
                if not clear_square(x, y, occupied):
                    continue
                for facing in ("N", "E", "S", "W"):
                    if facing == "N":
                        fx, fy = x, y - 2
                    elif facing == "E":
                        fx, fy = x + 2, y
                    elif facing == "S":
                        fx, fy = x, y + 2
                    else:
                        fx, fy = x - 2, y

                    if clear_square(fx, fy, occupied):
                        distance = abs(px - x) + abs(py - y)
                        candidates.append((distance, x, y, facing, fx, fy))

    candidates.sort()
    built = False

    for candidate in candidates:
        if world.decisions_left() <= 8:
            break

        distance, x, y, facing, fx, fy = candidate
        if not walk_to(x, y):
            continue
        if not world.place("burner-mining-drill", x, y, facing):
            continue

        drill = find_machine("mining-drill", x, y)
        if drill is not None:
            world.give(drill, "coal", 20)

        if not walk_to(fx, fy):
            continue
        if not world.place("stone-furnace", fx, fy, "N"):
            continue

        furnace = find_machine("furnace", fx, fy)
        if furnace is not None:
            world.give(furnace, "coal", 20)
        built = True
        break

    if built:
        while world.decisions_left() > 0:
            world.wait()

